-border);border-radius:.85rem;background:var(--wf-panel);padding:.85rem}.wf-catalog__filter summary{cursor:pointer;font-weight:800}.wf-catalog__filter-count{color:var(--wf-muted);font-weight:700}.wf-catalog__filter-list{display:grid;gap:.55rem;margin-top:.75rem}.wf-catalog__filter label{display:flex;align-items:flex-start;gap:.55rem;font-size:.9rem}.wf-catalog__filter input{width:1rem;min-height:1rem;margin-top:.15rem}.wf-catalog__filter small{margin-left:auto;color:var(--wf-muted)}.wf-catalog__results{display:grid;grid-template-columns:repeat(var(--wf-cols-desktop),minmax(0,1fr));gap:1rem}.wf-product{display:flex;min-width:0;flex-direction:column;overflow:hidden;border:1px solid var(--wf-border);border-radius:1rem;background:var(--wf-panel);box-shadow:0 6px 22px rgba(16,34,48,.06)}.wf-product__link{display:flex;flex:1;flex-direction:column;min-width:0;color:inherit;text-decoration:none}.wf-product__media{display:block;aspect-ratio:1/1;background:var(--wf-color-secondary,#f1f4f6);overflow:hidden}.wf-catalog[data-image-ratio="1/1"] .wf-product__media{aspect-ratio:1/1}.wf-catalog[data-image-ratio="4/3"] .wf-product__media{aspect-ratio:4/3}.wf-catalog[data-image-ratio="3/4"] .wf-product__media{aspect-ratio:3/4}.wf-product__media img{width:100%;height:100%;object-fit:contain;transition:transform .2s ease}.wf-product:hover .wf-product__media img{transform:scale(1.03)}.wf-product__content{display:flex;flex:1;flex-direction:column;padding:1rem}.wf-product__meta{margin:0 0 .35rem;color:var(--wf-muted);font-size:.77rem;text-transform:uppercase;letter-spacing:.05em}.wf-product h2{margin:0;font-size:1rem;line-height:1.35}.wf-product__footer{display:flex;align-items:flex-end;justify-content:space-between;gap:.5rem;margin-top:auto;padding-top:1rem}.wf-product__price{font-size:1.08rem;font-weight:850}.wf-product__stock{color:#197149;font-size:.78rem}.wf-product__stock[data-empty=true]{color:#a63d3d}.wf-catalog[data-layout=list] .wf-catalog__results{grid-template-columns:1fr}.wf-c