.wf-catalog[data-layout="list"] .wf-product__description{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}
.wf-catalog__range{display:grid;grid-template-columns:minmax(0,1fr);gap:.75rem;min-width:0}.wf-catalog__range-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}
.wf-catalog__range-fields label{display:grid;min-width:0;gap:.25rem}.wf-catalog__filter .wf-catalog__range-fields input{width:100%;min-width:0;min-height:2.75rem;margin:0;padding:.5rem}.wf-catalog__range-fields button{grid-column:1/-1}
