.wf-catalog__range-sliders input::-webkit-slider-thumb{-webkit-appearance:none;pointer-events:auto;width:1.4rem;height:1.4rem;border:2px solid var(--wf-panel);border-radius:50%;background:var(--wf-accent);box-shadow:0 0 0 1px var(--wf-accent);cursor:grab}
.wf-catalog__range-sliders input::-moz-range-thumb{pointer-events:auto;width:1.4rem;height:1.4rem;border:2px solid var(--wf-panel);border-radius:50%;background:var(--wf-accent);cursor:grab}
.wf-catalog__range-sliders input:focus-visible{outline:2px solid var(--wf-text);outline-offset:3px}.wf-catalog__range-fields input[aria-invalid="true"]{outline:2px solid #a12626}
